//! Unicode general categories and the four normalization forms (NFC, NFD, NFKC, NFKD), table driven
//! (`unicode_data.rs`, generated by `tools/gen_unicode_tables.py`) so tokenizers need no external crate.

use super::unicode_data::*;

/// General category of `c` as its two-letter name (`"Lu"`, `"Nd"`, `"Po"`, ...); `"Cn"` for unassigned.
pub fn category(c: char) -> &'static str {
    let cp = c as u32;
    let i = CATEGORY_RUNS.partition_point(|&(s, _)| s <= cp);
    CATEGORY_NAMES[CATEGORY_RUNS[i - 1].1 as usize]
}

/// `true` when the general category of `c` starts with `major` (`'L'`, `'M'`, `'N'`, `'P'`, `'S'`, `'Z'`, `'C'`).
pub fn is_major(c: char, major: u8) -> bool {
    category(c).as_bytes()[0] == major
}

/// Letters (`\p{L}`).
pub fn is_letter(c: char) -> bool {
    is_major(c, b'L')
}
/// Numbers (`\p{N}`).
pub fn is_number(c: char) -> bool {
    is_major(c, b'N')
}
/// Combining marks (`\p{M}`).
pub fn is_mark(c: char) -> bool {
    is_major(c, b'M')
}
/// Punctuation (`\p{P}`).
pub fn is_punctuation(c: char) -> bool {
    is_major(c, b'P')
}
/// Symbols (`\p{S}`).
pub fn is_symbol(c: char) -> bool {
    is_major(c, b'S')
}

/// Canonical combining class (0 for starters).
pub fn combining_class(c: char) -> u8 {
    let cp = c as u32;
    let i = COMBINING_CLASS.partition_point(|&(s, _, _)| s <= cp);
    if i > 0 && cp <= COMBINING_CLASS[i - 1].1 { COMBINING_CLASS[i - 1].2 } else { 0 }
}

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn lookup(index: &[(u32, u32, u8)], pool: &'static [u32], cp: u32) -> Option<&'static [u32]> {
    let i = index.binary_search_by_key(&cp, |&(c, _, _)| c).ok()?;
    let (_, off, n) = index[i];
    Some(&pool[off as usize..off as usize + n as usize])
}

fn push_decomposed<T: Copy>(c: char, tag: T, compat: bool, out: &mut Vec<(char, T)>) {
    let cp = c as u32;
    if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
        let s = cp - S_BASE;
        out.push((char::from_u32(L_BASE + s / N_COUNT).unwrap(), tag));
        out.push((char::from_u32(V_BASE + (s % N_COUNT) / T_COUNT).unwrap(), tag));
        if s % T_COUNT != 0 {
            out.push((char::from_u32(T_BASE + s % T_COUNT).unwrap(), tag));
        }
        return;
    }
    let hit = if compat {
        lookup(DECOMP_COMPAT_INDEX, DECOMP_COMPAT_POOL, cp)
    } else {
        lookup(DECOMP_CANON_INDEX, DECOMP_CANON_POOL, cp)
    };
    match hit {
        Some(parts) => out.extend(parts.iter().map(|&p| (char::from_u32(p).unwrap(), tag))),
        None => out.push((c, tag)),
    }
}

/// Canonical (or, with `compat`, compatibility) decomposition with the canonical ordering algorithm applied. Every
/// output character keeps the payload of the character it came from (used to track offsets).
pub fn decompose_with<T: Copy>(chars: &[(char, T)], compat: bool) -> Vec<(char, T)> {
    let mut out = Vec::with_capacity(chars.len());
    for &(c, t) in chars {
        push_decomposed(c, t, compat, &mut out);
    }
    // canonical ordering: stable sort of each run of non-starters by combining class
    let mut i = 0;
    while i < out.len() {
        if combining_class(out[i].0) == 0 {
            i += 1;
            continue;
        }
        let start = i;
        while i < out.len() && combining_class(out[i].0) != 0 {
            i += 1;
        }
        out[start..i].sort_by_key(|&(c, _)| combining_class(c));
    }
    out
}

fn compose_pair(a: char, b: char) -> Option<char> {
    let (x, y) = (a as u32, b as u32);
    if (L_BASE..L_BASE + L_COUNT).contains(&x) && (V_BASE..V_BASE + V_COUNT).contains(&y) {
        return char::from_u32(S_BASE + ((x - L_BASE) * V_COUNT + (y - V_BASE)) * T_COUNT);
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&x) && (x - S_BASE) % T_COUNT == 0 && (T_BASE + 1..T_BASE + T_COUNT).contains(&y) {
        return char::from_u32(x + (y - T_BASE));
    }
    let i = COMPOSE_PAIRS.binary_search_by_key(&(x, y), |&(p, q, _)| (p, q)).ok()?;
    char::from_u32(COMPOSE_PAIRS[i].2)
}

/// Canonical composition of an already decomposed sequence; `merge` combines the payloads of a composed pair.
pub fn compose_with<T: Copy>(chars: Vec<(char, T)>, merge: impl Fn(T, T) -> T) -> Vec<(char, T)> {
    let mut out: Vec<(char, T)> = Vec::with_capacity(chars.len());
    let mut starter: Option<usize> = None;
    for (c, t) in chars {
        let cc = combining_class(c);
        if let Some(si) = starter {
            // `c` is blocked from the starter when a character of equal or higher class lies between them
            let adjacent = out.len() - 1 == si;
            let blocked = !adjacent && combining_class(out.last().unwrap().0) >= cc;
            if !blocked {
                if let Some(p) = compose_pair(out[si].0, c) {
                    out[si] = (p, merge(out[si].1, t));
                    continue;
                }
            }
        }
        if cc == 0 {
            starter = Some(out.len());
        }
        out.push((c, t));
    }
    out
}

fn run(text: &str, compat: bool, compose: bool) -> String {
    let chars: Vec<(char, ())> = text.chars().map(|c| (c, ())).collect();
    let d = decompose_with(&chars, compat);
    let d = if compose { compose_with(d, |a, _| a) } else { d };
    d.into_iter().map(|(c, _)| c).collect()
}

/// Canonical decomposition.
pub fn nfd(text: &str) -> String {
    run(text, false, false)
}
/// Compatibility decomposition.
pub fn nfkd(text: &str) -> String {
    run(text, true, false)
}
/// Canonical decomposition followed by canonical composition.
pub fn nfc(text: &str) -> String {
    run(text, false, true)
}
/// Compatibility decomposition followed by canonical composition.
pub fn nfkc(text: &str) -> String {
    run(text, true, true)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn categories_and_forms() {
        assert_eq!(category('A'), "Lu");
        assert_eq!(category('é'), "Ll");
        assert_eq!(category('7'), "Nd");
        assert_eq!(category('!'), "Po");
        assert_eq!(category('$'), "Sc");
        assert_eq!(category('\u{0301}'), "Mn");
        assert!(is_letter('世') && is_number('²') && is_punctuation('«') && is_symbol('+') && is_mark('\u{0301}'));
        assert_eq!(combining_class('\u{0301}'), 230);
        assert_eq!(nfd("é"), "e\u{0301}");
        assert_eq!(nfc("e\u{0301}"), "é");
        assert_eq!(nfkc("ﬁ ㎏ ①"), "fi kg 1");
        assert_eq!(nfd("한"), "\u{1112}\u{1161}\u{11AB}");
        assert_eq!(nfc("\u{1112}\u{1161}\u{11AB}"), "한");
        // canonical ordering: dot below (220) goes before acute (230)
        assert_eq!(nfd("a\u{0301}\u{0323}"), "a\u{0323}\u{0301}");
        assert_eq!(nfc("a\u{0301}\u{0323}"), "\u{1EA1}\u{0301}");
    }
}
